// public/shared/pitch-course.js
var A42 = Object.freeze({ hz: 440, note: 69 });
var SEMITONES_PER_OCTAVE = 12;
var CENTS_PER_SEMITONE = 100;
var CENTS_PER_OCTAVE = SEMITONES_PER_OCTAVE * CENTS_PER_SEMITONE;
var FIGURE_PLACES = Object.freeze({ cents: 0, seconds: 3, holdSeconds: 2, clarity: 2 });
var SWING_QUANTILES = Object.freeze([0.1, 0.9]);
var PITCH_COURSE = Object.freeze({
  hopSeconds: 0.02,
  // a course's frames every 20 ms once past its attack (a slide or a sweep is slower)
  clarity: 0.5,
  // a frame this periodic or more has a pitch
  settleSeconds: 0.1,
  // a note has settled where its smoothed pitch then stays within holdCents this long
  holdCents: 50,
  // within a quarter tone: the same pitch
  lastingSeconds: 0.05,
  // a departure counts when it lasts 50 ms
  smoothingSeconds: 0.25,
  // a centred moving median this long takes a vibrato of 4 Hz or faster away
  keytrackCents: 50,
  prominenceDb: 6,
  // the loudest partial counts as a resonance where it stands this far over the next
  secondNoteCents: 100,
  // a resonance on a pitch class a semitone or more from the note's own is another note,
  // heard as one where it lasts lastingSeconds and moves (secondNote): ours
  whistleDb: 20,
  // ... or, held still, where it stands this far over the next: a whistle of its own (ours)
  attackDb: 3,
  quietDb: 30,
  // a frame this far under the note's loudest is not judged: a note fading is not moving
  settleFrames: 3
  // and the stretch it settles over holds this many clear frames at least
});

